pub(super) fn reject_non_dependency_discovery(
    value: &JsonMap<String, JsonValue>,
    label: &str,
) -> Result<()> {
    for field in ["bundledDependencies", "bundleDependencies"] {
        if let Some(entry) = value.get(field) {
            let empty = entry.as_array().is_some_and(Vec::is_empty);
            if !empty {
                bail!("{label} must not contain bundled dependencies");
            }
        }
    }
    if value.contains_key("workspaces") {
        bail!("{label} must not contain workspace dependency discovery");
    }
    Ok(())
}

pub(super) fn validate_lock_header(
    lock: &JsonMap<String, JsonValue>,
    name: &str,
    version: &str,
) -> Result<()> {
    if lock.get("lockfileVersion").and_then(JsonValue::as_u64) != Some(3) {
        bail!("npm package lock must use lockfileVersion 3");
    }
    require_bool(lock, "requires", true)?;
    validate_identity(lock, name, version, "npm package lock")
}

pub(super) fn validate_identity(
    value: &JsonMap<String, JsonValue>,
    name: &str,
    version: &str,
    label: &str,
) -> Result<()> {
    if value.get("name").and_then(JsonValue::as_str) != Some(name)
        || value.get("version").and_then(JsonValue::as_str) != Some(version)
    {
        bail!("{label} identity does not match the manifest");
    }
    Ok(())
}

