    let raw = serde_json::to_string(&drift).unwrap();
    assert!(!raw.contains("PRIVATE_SCRIPT_DRIFT_SENTINEL"));
    assert!(!raw.contains("capsule.lua"));
    fs::copy(&script, &materialized).unwrap();

    let unsafe_script = work.path().join("unsafe.lua");
    fs::write(
        &unsafe_script,
        "function transform(input) return os.execute(input) end\n",
    )
    .unwrap();
    let unsafe_module = provision(work.path(), &unsafe_script, "lua.foreign.unsafe");
    let unsafe_rejected = rejected(
        work.path(),
        "invoke",
        unsafe_module["module_cid"].as_str().unwrap(),
        Some("cmd.exe"),
    );
    assert_rejected_without_child_disclosure(&unsafe_rejected, "child_exit_nonzero");

    let loop_script = work.path().join("loop.lua");
    fs::write(
        &loop_script,
        "function transform(input) while true do end end\n",
    )
    .unwrap();
    let loop_module = provision(work.path(), &loop_script, "lua.foreign.loop");
